#define MAX_FILE_SIZE (256 * 1024 * 1024)

char *read_file_to_buffer(const char *filename, size_t *out_size) {
    if (filename == NULL || out_size == NULL) {
        return NULL;
    }

    *out_size = 0;

    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    int fd = fileno(file);
    if (fd < 0) {
        fclose(file);
        return NULL;
    }

    struct stat st;
    if (fstat(fd, &st) != 0) {
        fclose(file);
        return NULL;
    }

    if (!S_ISREG(st.st_mode)) {
        fclose(file);
        return NULL;
    }

    if (st.st_size < 0) {
        fclose(file);
        return NULL;
    }

    if ((uintmax_t)st.st_size > MAX_FILE_SIZE) {
        fclose(file);
        return NULL;
    }

    if ((uintmax_t)st.st_size > SIZE_MAX - 1) {
        fclose(file);
        return NULL;
    }

    size_t size = (size_t)st.st_size;
    char *buffer = malloc(size + 1);
    if (buffer == NULL) {
        fclose(file);
        return NULL;
    }

    size_t bytes_read = 0;
    while (bytes_read < size) {
        size_t n = fread(buffer + bytes_read, 1, size - bytes_read, file);
        if (n == 0) {
            if (ferror(file)) {
                free(buffer);
                fclose(file);
                return NULL;
            }
            break;
        }
        bytes_read += n;
    }

    if (bytes_read != size) {
        free(buffer);
        fclose(file);
        return NULL;
    }

    buffer[size] = '\0';
    *out_size = size;

    fclose(file);
    return buffer;
}

