    PARSE_INT_ERR_NULL,
    PARSE_INT_ERR_EMPTY,
    PARSE_INT_ERR_OVERFLOW,
    PARSE_INT_ERR_INVALID
} parse_int_result_t;

/*
 * Parses a base-10 integer from `str` into `*out_value`.
 *
 * Behaviour:
 *   - Leading and trailing whitespace is ignored.
 *   - An optional '+' or '-' sign is accepted.
 *   - At least one digit must follow the sign.
 *   - No trailing non-whitespace characters are allowed.
 *   - Overflow (value outside [INT_MIN, INT_MAX]) is detected and reported.
 *
 * Returns PARSE_INT_OK on success, or an error code otherwise.
 */
parse_int_result_t parse_int(const char *str, int *out_value)
{
    const char *p;
    int sign = 1;
    unsigned long long accumulator = 0;
    unsigned long long limit;
    int digit;

    if (str == NULL || out_value == NULL) {
        return PARSE_INT_ERR_NULL;
    }

    p = str;

    /* Skip leading whitespace */
    while (*p == ' ' || *p == '\t' || *p == '\n' ||
           *p == '\r' || *p == '\v' || *p == '\f') {
        p++;
    }

    if (*p == '\0') {
        return PARSE_INT_ERR_EMPTY;
    }

    /* Handle optional sign */
    if (*p == '+') {
        p++;
    } else if (*p == '-') {
        sign = -1;
        p++;
    }

    /* Require at least one digit after optional sign */
    if (*p < '0' || *p > '9') {
        return PARSE_INT_ERR_INVALID;
    }

    /*
     * Maximum magnitude we can accept:
     *   Positive: INT_MAX
     *   Negative: |INT_MIN| == (unsigned long long)INT_MAX + 1
     */
    limit = (sign == 1) ? (unsigned long long)INT_MAX
                        : (unsigned long long)INT_MAX + 1ULL;

    while (*p >= '0' && *p <= '9') {
        digit = *p - '0';

        /* Check overflow before multiplying by 10 */
        if (accumulator > limit / 10U) {
            return PARSE_INT_ERR_OVERFLOW;
        }
        accumulator *= 10ULL;

        /* Check overflow before adding the digit */
        if ((unsigned long long)digit > limit - accumulator) {
            return PARSE_INT_ERR_OVERFLOW;
        }
        accumulator += (unsigned long long)digit;

        p++;
    }

    /* Skip trailing whitespace */
    while (*p == ' ' || *p == '\t' || *p == '\n' ||
           *p == '\r' || *p == '\v' || *p == '\f') {
        p++;
    }

    /* Reject if there are leftover non-whitespace characters */
    if (*p != '\0') {
        return PARSE_INT_ERR_INVALID;
    }

    /* Convert unsigned accumulator back to signed int safely */
    if (sign == 1) {
        /* accumulator <= INT_MAX, so the cast is well-defined */
        *out_value = (int)accumulator;
    } else {
        if (accumulator > (unsigned long long)INT_MAX) {
            /* Only possible value is INT_MAX + 1, which maps to INT_MIN */
            *out_value = INT_MIN;
        } else {
            *out_value = -(int)accumulator;
        }
    }

    return PARSE_INT_OK;
}

