typedef struct TreeNode {
    char *data;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

#define MAX_TREE_DEPTH 4096

void free_tree(TreeNode *root) {
    if (root == NULL) {
        return;
    }

    /* Iterative post-order traversal to prevent stack overflow
       from deeply nested or degenerate trees */
    TreeNode *stack[MAX_TREE_DEPTH];
    int top = 0;
    TreeNode *last_visited = NULL;
    TreeNode *current = root;

    while (current != NULL || top > 0) {
        /* Traverse to leftmost node, pushing nodes onto stack */
        while (current != NULL) {
            if (top >= MAX_TREE_DEPTH) {
                /* Tree exceeds safe depth limit; abort to prevent overflow */
                return;
            }
            stack[top++] = current;
            current = current->left;
        }

        TreeNode *peek = stack[top - 1];

        /* If right child exists and hasn't been visited, traverse right */
        if (peek->right != NULL && peek->right != last_visited) {
            current = peek->right;
        } else {
            /* Pop and free the node */
            TreeNode *node = stack[--top];
            last_visited = node;

            /* Safe free of data with NULL assignment */
            if (node->data != NULL) {
                free(node->data);
                node->data = NULL;
            }

            /* Clear child pointers to prevent use-after-free */
            node->left = NULL;
            node->right = NULL;

            free(node);
        }
    }
}

