/**
 * Parses command-line arguments to extract the filename specified after
 * the --output flag. Supports both "--output <filename>" and
 * "--output=<filename>" forms.
 *
 * @param argc      Argument count from main().
 * @param argv      Argument vector from main().
 * @param out_buf   Destination buffer for the filename (must not be NULL).
 * @param buf_size  Size of out_buf in bytes (must be > 0).
 *
 * @return   0 on success,
 *          -1 if any argument is invalid (NULL pointers, bad sizes),
 *          -2 if --output was not found,
 *          -3 if --output was found but no filename was provided,
 *          -4 if the filename is empty,
 *          -5 if the filename would not fit in out_buf.
 */
int parse_output_filename(int argc, char **argv,
                          char *out_buf, size_t buf_size)
{
    static const char flag[] = "--output";
    static const size_t flag_len = sizeof(flag) - 1; /* excludes NUL */
    const char *filename = NULL;
    size_t filename_len;
    int i;

    /* --- Parameter validation --- */
    if (argv == NULL || out_buf == NULL) {
        return -1;
    }
    if (argc < 0 || buf_size == 0) {
        return -1;
    }

    /* Ensure every argv entry we might access is non-NULL */
    for (i = 0; i < argc; i++) {
        if (argv[i] == NULL) {
            return -1;
        }
    }

    /* --- Scan for the --output flag --- */
    for (i = 1; i < argc; i++) {
        const char *arg = argv[i];
        size_t arg_len = strlen(arg);

        /* Form: --output=<filename> */
        if (arg_len > flag_len && arg[flag_len] == '=' &&
            memcmp(arg, flag, flag_len) == 0) {
            filename = arg + flag_len + 1;
            break;
        }

        /* Form: --output <filename> (exact match) */
        if (arg_len == flag_len && memcmp(arg, flag, flag_len) == 0) {
            if (i + 1 >= argc) {
                return -3; /* flag present but no following argument */
            }
            filename = argv[i + 1];
            break;
        }
    }

    if (filename == NULL) {
        return -2; /* --output not found */
    }

    /* --- Validate and copy the filename --- */
    filename_len = strlen(filename);
    if (filename_len == 0) {
        return -4; /* empty filename */
    }

    /* Ensure room for filename plus NUL terminator */
    if (filename_len >= buf_size) {
        return -5; /* would overflow out_buf */
    }

    memcpy(out_buf, filename, filename_len);
    out_buf[filename_len] = '\0';

    return 0;
}

