char *read_file_to_buffer(const char *filename, size_t *out_size) {
    if (filename == NULL) {
        return NULL;
    }

    const size_t MAX_FILE_SIZE = 256 * 1024 * 1024;

    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return NULL;
    }

    long file_size = ftell(file);
    if (file_size < 0) {
        fclose(file);
        return NULL;
    }

    if ((unsigned long)file_size > MAX_FILE_SIZE) {
        fclose(file);
        return NULL;
    }

    if (fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return NULL;
    }

    size_t size = (size_t)file_size;

    /* Prevent integer overflow when adding 1 for null terminator */
    if (size > SIZE_MAX - 1) {
        fclose(file);
        return NULL;
    }

    size_t alloc_size = size + 1;

    /* Use calloc to zero-initialize memory, preventing information leaks */
    char *buffer = (char *)calloc(alloc_size, 1);
    if (buffer == NULL) {
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, size, file);

    /* Check for read errors - any short read is an error */
    if (bytes_read != size) {
        free(buffer);
        fclose(file);
        return NULL;
    }

    /* Null-terminate at the actual number of bytes read */
    buffer[bytes_read] = '\0';

    if (out_size != NULL) {
        *out_size = bytes_read;
    }

    fclose(file);
    return buffer;
}

