int parse_int_safe(const char *str, int *result) {
    if (str == NULL || result == NULL) {
        errno = EINVAL;
        return -1;
    }

    const char *p = str;

    while (isspace((unsigned char)*p)) {
        p++;
    }

    int sign = 1;
    if (*p == '+') {
        p++;
    } else if (*p == '-') {
        sign = -1;
        p++;
    }

    if (!isdigit((unsigned char)*p)) {
        errno = EINVAL;
        return -1;
    }

    long long acc = 0;
    while (isdigit((unsigned char)*p)) {
        int digit = *p - '0';

        if (acc > (LLONG_MAX - digit) / 10) {
            errno = ERANGE;
            return -1;
        }
        acc = acc * 10 + digit;
        p++;
    }

    while (isspace((unsigned char)*p)) {
        p++;
    }

    if (*p != '\0') {
        errno = EINVAL;
        return -1;
    }

    acc *= sign;

    if (acc < INT_MIN || acc > INT_MAX) {
        errno = ERANGE;
        return -1;
    }

    *result = (int)acc;
    return 0;
}

