void *safe_memmove(void *dest, const void *src, size_t n) {
    if (n == 0) {
        return dest;
    }

    if (dest == NULL || src == NULL) {
        return NULL;
    }

    unsigned char *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    uintptr_t d_addr = (uintptr_t)dest;
    uintptr_t s_addr = (uintptr_t)src;

    /* 
     * If destination is ahead of source and they overlap,
     * copying forward would corrupt the data. 
     * Copy backward instead.
     */
    if (d_addr > s_addr && (d_addr - s_addr) < n) {
        d += n - 1;
        s += n - 1;
        while (n--) {
            *d-- = *s--;
        }
    } else {
        /* 
         * Otherwise, copy forward. This handles non-overlapping 
         * regions and cases where source is ahead of destination.
         */
        while (n--) {
            *d++ = *s++;
        }
    }

    return dest;
}

