#include <stdlib.h>

typedef struct TreeNode {
    char *str;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

void tree_free(TreeNode **root) {
    if (root == NULL || *root == NULL) {
        return;
    }

    /* Iterative approach using tree rotation to prevent stack overflow
     * on deeply nested/degenerate trees */
    while (*root != NULL) {
        TreeNode *node = *root;

        if (node->left != NULL) {
            /* Rotate left child up to root position, moving current
             * node to right subtree of left child */
            TreeNode *left = node->left;
            node->left = left->right;
            left->right = node;
            *root = left;
        } else if (node->right != NULL) {
            /* No left child; promote right child and free current node */
            *root = node->right;

            if (node->str != NULL) {
                free(node->str);
                node->str = NULL;
            }
            node->left = NULL;
            node->right = NULL;
            free(node);
        } else {
            /* Leaf node - free it and terminate */
            if (node->str != NULL) {
                free(node->str);
                node->str = NULL;
            }
            free(node);
            *root = NULL;
        }
    }
}

