int format_log_message(char *buffer, size_t buffer_size, const char *log_level, const char *message) {
    if (buffer == NULL || buffer_size == 0 || log_level == NULL || message == NULL) {
        return -1;
    }

    time_t raw_time;
    struct tm time_info;
    char time_str[32];

    if (time(&raw_time) == (time_t)-1) {
        return -1;
    }

    if (localtime_r(&raw_time, &time_info) == NULL) {
        return -1;
    }

    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &time_info) == 0) {
        return -1;
    }

    int result = snprintf(buffer, buffer_size, "[%s] [%s] %s", time_str, log_level, message);

    if (result < 0) {
        return -1;
    }

    if ((size_t)result >= buffer_size) {
        buffer[buffer_size - 1] = '\0';
        return (int)(buffer_size - 1);
    }

    return result;
}

