    if (log_level_strings[level] == NULL) {
        return -1;
    }

    if (message == NULL) {
        message = "(null)";
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        return -1;
    }

    /* snprintf returns the number of chars that WOULD be written; clamp to actual */
    int needed = snprintf(buffer, size, "[%s] [%s] %s", 
                          timestamp, 
                          log_level_strings[level], 
                          message);

    if (needed < 0) {
        buffer[0] = '\0';
        return -1;
    }

    /* If truncation occurred, return actual bytes written (size - 1) */
    if ((size_t)needed >= size) {
        /* Ensure null termination even though snprintf guarantees it */
        buffer[size - 1] = '\0';
        return (int)(size - 1);
    }

    return needed;
}

