 * Parses command-line arguments for the --output flag.
 *
 * Supports two forms:
 *   --output <filename>
 *   --output=<filename>
 *
 * Parameters:
 *   argc      - argument count from main()
 *   argv      - argument vector from main()
 *   dest      - destination buffer to receive the filename
 *   dest_size - size of dest buffer in bytes
 *
 * Returns:
 *    0  on success (filename copied to dest, null-terminated)
 *   -1  on invalid arguments (NULL pointers, zero buffer size, argc < 1)
 *   -2  if --output flag was not found
 *   -3  if --output flag present but no filename value provided
 *   -4  if filename is too long for destination buffer
 */
int parse_output_flag(int argc, char *argv[], char *dest, size_t dest_size)
{
    int i;
    const char *filename = NULL;
    size_t flag_eq_len;
    size_t filename_len;

    /* Validate inputs */
    if (argv == NULL || dest == NULL) {
        return -1;
    }
    if (dest_size == 0 || argc < 1) {
        return -1;
    }

    /* Validate all argv entries are non-NULL (defensive) */
    for (i = 0; i < argc; i++) {
        if (argv[i] == NULL) {
            return -1;
        }
    }

    flag_eq_len = strlen(OUTPUT_FLAG_EQ);

    /* Scan arguments starting from index 1 (skip program name) */
    for (i = 1; i < argc; i++) {
        size_t arg_len = strlen(argv[i]);

        /* Form: --output=filename */
        if (arg_len >= flag_eq_len &&
            strncmp(argv[i], OUTPUT_FLAG_EQ, flag_eq_len) == 0) {
            filename = argv[i] + flag_eq_len;
            if (*filename == '\0') {
                return -3;  /* empty value after '=' */
            }
            break;
        }

        /* Form: --output filename */
        if (strcmp(argv[i], OUTPUT_FLAG) == 0) {
            if (i + 1 >= argc) {
                return -3;  /* no argument follows the flag */
            }
            filename = argv[i + 1];
            if (*filename == '\0') {
                return -3;  /* empty filename */
            }
            break;
        }
    }

    /* Flag not found */
    if (filename == NULL) {
        return -2;
    }

    /* Bounds check before copying (use strnlen for additional safety) */
    filename_len = strnlen(filename, dest_size);
    if (filename_len >= dest_size) {
        return -4;  /* filename too long for buffer */
    }

    /* Safe copy with explicit null termination */
    memcpy(dest, filename, filename_len);
    dest[filename_len] = '\0';

    return 0;
}

#include <string.h>
#include <stddef.h>

#define PARSE_OK                     0
#define PARSE_ERR_NULL_PTR          (-1)
#define PARSE_ERR_INVALID_ARGS      (-2)
#define PARSE_ERR_NOT_FOUND         (-3)
#define PARSE_ERR_MISSING_VALUE     (-4)
#define PARSE_ERR_BUFFER_TOO_SMALL  (-5)

#define MAX_FILENAME_LEN            4096
#define MAX_ARGC_LIMIT              100000

int parse_output_filename(int argc, char *const argv[],
                          char *out_buf, size_t buf_size)
{
    if (argv == NULL || out_buf == NULL) {
        return PARSE_ERR_NULL_PTR;
    }
    if (argc <= 0 || argc > MAX_ARGC_LIMIT || buf_size == 0) {
        return PARSE_ERR_INVALID_ARGS;
    }

    const char *const flag = "--output";
    const size_t flag_len = strlen(flag);

    for (int i = 1; i < argc; i++) {
        if (argv[i] == NULL) {
            return PARSE_ERR_INVALID_ARGS;
        }

        if (strcmp(argv[i], "--") == 0) {
            break;
        }

        size_t arg_len = strlen(argv[i]);

        /* Skip if argument is shorter than flag or doesn't match prefix */
        if (arg_len < flag_len || strncmp(argv[i], flag, flag_len) != 0) {
            continue;
        }

        /* Handle --output=filename form */
        if (arg_len > flag_len && argv[i][flag_len] == '=') {
            const char *filename = argv[i] + flag_len + 1;
            size_t filename_len = strlen(filename);

            if (filename_len == 0) {
                return PARSE_ERR_MISSING_VALUE;
            }
            /* Ensure filename + null terminator fits in buffer */
            if (filename_len >= buf_size || filename_len > MAX_FILENAME_LEN) {
                return PARSE_ERR_BUFFER_TOO_SMALL;
            }
            memcpy(out_buf, filename, filename_len);
            out_buf[filename_len] = '\0';
            return PARSE_OK;
        }

        /* Handle --output filename form */
        if (arg_len == flag_len) {
            if (i + 1 >= argc) {
                return PARSE_ERR_MISSING_VALUE;
            }
            if (argv[i + 1] == NULL) {
                return PARSE_ERR_INVALID_ARGS;
            }

            const char *filename = argv[i + 1];
            size_t filename_len = strlen(filename);

            if (filename_len == 0) {
                return PARSE_ERR_MISSING_VALUE;
            }
            /* Ensure filename + null terminator fits in buffer */
            if (filename_len >= buf_size || filename_len > MAX_FILENAME_LEN) {
                return PARSE_ERR_BUFFER_TOO_SMALL;
            }
            memcpy(out_buf, filename, filename_len);
            out_buf[filename_len] = '\0';
            return PARSE_OK;
        }
    }

    return PARSE_ERR_NOT_FOUND;
}
